import EstranCore
import SwiftUI

/// A friendly extra recommendation, distinct from the deterministic reason.
///
/// Until M4 (Foundation Models), this is a **template** chosen from the
/// activity. It is never presented as generated by Apple Intelligence, and it
/// never contradicts the verdict.
struct TipCard: View {
    let activity: Activity

    var body: some View {
        HStack(alignment: .top, spacing: OceanSpacing.sm) {
            Image(systemName: "sparkles")
                .font(OceanTypography.body)
                .foregroundStyle(OceanPalette.turquoise)
                .accessibilityHidden(true)

            VStack(alignment: .leading, spacing: OceanSpacing.xxs) {
                Text("Conseil")
                    .font(OceanTypography.smallLabel)
                    .foregroundStyle(OceanPalette.sand)
                Text(tip)
                    .font(OceanTypography.caption)
                    .foregroundStyle(OceanPalette.white.opacity(0.9))
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(OceanSpacing.md)
        .oceanGlassCard(cornerRadius: OceanGlass.tileCornerRadius)
        .accessibilityElement(children: .combine)
    }

    private var tip: String {
        switch activity {
        case .shoreFishing:
            "Pense aux bottes : le banc reste humide après la basse mer."
        case .surfing:
            "La houle rentre mieux à mi-marée. Surveille les séries."
        case .boating:
            "Vérifie la météo et les avis de coup de vent avant de partir."
        case .walking:
            "Le vent sèche vite sur la plage : prends une couche."
        case .swimming:
            "Baigne dans une zone surveillée, jamais seul, et garde les enfants à portée de main."
        }
    }
}
